formulas.rawText:
{
  "originalFormula": "J_{s} = e_{n} \cdot I_{s} \cdot \\left( \\frac{1}{N_{a} \\sqrt{D_{n} \\tau_{p}}} + \\frac{1}{N_{d} \\sqrt{D_{p} \\tau_{n}}} \\right)",
  "genericFormula": "J_{s} = e_{n} \\cdot I_{s} \\cdot \\left( \\frac{1}{N_{a} \\sqrt{D_{n} \\tau_{p}}} + \\frac{1}{N_{d} \\sqrt{D_{p} \\tau_{n}}} \\right)",
  "description": "Esta fórmula representa a densidade de corrente de saturação em um semicondutor, levando em consideração a contribuição de portadores de carga em diferentes regiões do material. Ela é fundamental para entender como os portadores se movem e se recombinam em um semicondutor dopado.",
  "concepts": [
    "Densidade de corrente",
    "Portadores de carga",
    "Recombinação de portadores",
    "Semicondutores dopados",
    "Mobilidade de portadores"
  ],
  "symbols": [
    {
      "symbol": "J_{s}",
      "description": "Representa a densidade de corrente de saturação, que é a quantidade de corrente por unidade de área em um semicondutor."
    },
    {
      "symbol": "e_{n}",
      "description": "Representa a carga elétrica do portador de carga negativa, que é o elétron."
    },
    {
      "symbol": "I_{s}",
      "description": "Representa a corrente de saturação, que é a corrente máxima que flui em um dispositivo semicondutor sob condições específicas."
    },
    {
      "symbol": "N_{a}",
      "description": "Representa a concentração de átomos do dopante aceitador no semicondutor, que influencia a quantidade de buracos disponíveis."
    },
    {
      "symbol": "D_{n}",
      "description": "Representa o coeficiente de difusão dos elétrons, que é uma medida de como os elétrons se espalham no material."
    },
    {
      "symbol": "tau_{p}",
      "description": "Representa o tempo médio de vida dos portadores de carga positiva, que são os buracos, antes de se recombinarem."
    },
    {
      "symbol": "N_{d}",
      "description": "Representa a concentração de átomos do dopante doador no semicondutor, que influencia a quantidade de elétrons disponíveis."
    },
    {
      "symbol": "D_{p}",
      "description": "Representa o coeficiente de difusão dos buracos, que é uma medida de como os buracos se espalham no material."
    },
    {
      "symbol": "tau_{n}",
      "description": "Representa o tempo médio de vida dos portadores de carga negativa, que são os elétrons, antes de se recombinarem."
    }
  ]
}
